  useEffect(()=>{onDraftChange({revenues,startup,funding,expenses,staff,loans,workingCapital,assetLives,fixedAssets,tax})},[revenues,startup,funding,expenses,staff,loans,workingCapital,assetLives,fixedAssets,tax,onDraftChange]);
