  const months=useMemo(()=>projectFinancials({revenues:revenues.map(row=>({...row,growth:Number(row.growth||0)/100,directCost:Number(row.directCost||0)/100})),expenses:expenseProjection.monthly,payroll,openingCash,taxRate:tax.incomeTaxRate,depreciableAssets,ownerDraws:tax.ownerDraws,inventory:startup.inventory}),[revenues,expenseProjection.monthly,payroll,openingCash,tax.incomeTaxRate,tax.ownerDraws,depreciableAssets,startup.inventory]);
  const centralAssumptions=useMemo(()=>({planId:'demo-plan',projectionStartDate:'2026-08-01',projectionMonths:36,currency,openingCash,initialCashReserve:Number(startup.initialCashReserve||0),revenueStreams:revenues.map((row,index)=>({id:`revenue-${index}`,name:row.name,startMonth:1,unitPrice:Number(row.price||0),monthlyUnits:Number(row.units||0),unitPriceByYear:[row.price,row.year2Price??row.price,row.year3Price??row.year2Price??row.price].map(Number),monthlyUnitsByYear:[row.units,row.year2Units??row.units,row.year3Units??row.year2Units??row.units].map(Number),monthlyGrowthRate:Number(row.growth||0),annualPriceIncreaseRate:Number(row.annualPriceIncrease||0)})),directCostAssumptions:revenues.map((row,index)=>({revenueStreamId:`revenue-${index}`,percentage:Number(row.directCost||0)})),startupProjectCosts:Object.entries(startup).filter(([key,amount])=>!['workingCapital','initialCashBalance','initialCashReserve'].includes(key)&&Number(amount)>0).map(([key,amount])=>({id:`cost-${key}`,name:key.replace(/([A-Z])/g,' $1'),amount:Number(amount),paymentMonth:1,type:['equipment','furniture','renovations','leaseholdImprovements','vehicle'].includes(key)?'capital_expenditure':key==='inventory'?'opening_inventory':key==='deposits'?'deposit_or_prepaid':'startup'})),operatingExpenses:expenses,payrollAssumptions:staff,fundingSources:[{id:'owner-investment',name:'Owner investment',type:'owner_contribution',amount:Number(funding.ownerInvestment||0),month:1},{id:'grant-funding',name:'Grant / government funding',type:'grant',amount:Number(funding.grantGovernmentFunding||0),month:1}].filter(source=>source.amount>0),loanAssumptions:loans,taxAssumptions:{incomeTaxRate:Number(tax.incomeTaxRate||0),paymentLagMonths:1},depreciationAssumptions:{assets:[...([['equipment','Equipment'],['furniture','Furniture'],['renovations','Renovations'],['leaseholdImprovements','Leasehold improvements'],['vehicle','Vehicle']].filter(([key])=>Number(startup[key]||0)>0).map(([key,name])=>({id:`fixed-${key}`,name,category:key,purchaseAmount:Number(startup[key]),purchaseMonth:1,inServiceMonth:1,usefulLifeMonths:Number(assetLives[key]||60),residualValue:0,depreciationMethod:'straight_line',sourceStartupCostId:`cost-${key}`}))),...fixedAssets.filter(asset=>Number(asset.purchaseAmount)>0).map(asset=>({...asset,purchaseAmount:Number(asset.purchaseAmount),purchaseMonth:Math.max(1,Number(asset.purchaseMonth)||1),inServiceMonth:Math.max(1,Number(asset.purchaseMonth)||1),usefulLifeMonths:Math.max(1,Number(asset.usefulLifeMonths)||60),residualValue:0,depreciationMethod:'straight_line'}))]},workingCapitalAssumptions:workingCapital}),[revenues,expenses,staff,openingCash,loans,tax.incomeTaxRate,startup,funding,currency,workingCapital,assetLives,fixedAssets]);
  const centralProjection=useMemo(()=>calculateFinancialProjection(centralAssumptions),[centralAssumptions]);
  const centralAnalysis=useMemo(()=>calculateFinancialAnalysis(centralProjection),[centralProjection]);
  useEffect(()=>{let live=true;calculateFinancialAssumptionsHash(centralAssumptions).then(assumptionsHash=>live&&onReviewChange({assumptions:centralAssumptions,projection:centralProjection,analysis:centralAnalysis,assumptionsHash,complete:centralAssumptions.revenueStreams.every(row=>row.name&&row.monthlyUnits>0)}));return()=>{live=false}},[centralAssumptions,centralProjection,centralAnalysis,onReviewChange]);
  const years=annualize(months);
  const analysis=financialAnalysis(months);
  const fieldGrid=(values,setter,fields)=><div className="financial-field-grid">{fields.map(([key,label,suffix])=><Field key={key} label={label+(suffix?` (${suffix})`:'')} value={values[key]} onChange={value=>updateObject(setter,key,value)}/>)}</div>;
  const startupFields=[['businessPurchase','Business purchase / acquisition cost','$'],['equipment','Equipment','$'],['furniture','Furniture','$'],['renovations','Renovations','$'],['leaseholdImprovements','Leasehold improvements','$'],['inventory','Inventory','$'],['deposits','Deposits','$'],['website','Website','$'],['software','Software','$'],['legalFees','Legal fees','$'],['accountingFees','Accounting fees','$'],['marketing','Marketing','$'],['licensing','Licensing','$'],['insurance','Insurance','$'],['vehicle','Vehicle','$'],['otherCosts','Other project costs','$'],['initialCashReserve','Initial working capital / cash reserve','$']];
  const totalProjectCost=Object.entries(startup).reduce((sum,[key,value])=>sum+(['workingCapital','initialCashBalance'].includes(key)?0:Number(value||0)),0)+fixedAssets.reduce((sum,asset)=>sum+Number(asset.purchaseAmount||0),0);
